UPDATE tb_crawl_document
SET content_tokens = #{tokens}
WHERE crawl_document_no = #{id}

mapper.select:
SELECT coverage_no, target_no, run_log_no, list_pages, list_items_found, details_fetched, details_failed, truncated_yn, frst_reg_dt
FROM tb_crawl_coverage


        target_no = #{targetId}


