        target_no = #{targetId}


        AND status = #{status}


        AND failure_code = #{failureCode}


ORDER BY frst_reg_dt DESC, crawl_run_log_no DESC
LIMIT #{limit}

SELECT 
FROM tb_crawl_job


        target_no = #{targetId}


ORDER BY requested_at DESC, crawl_job_no DESC
LIMIT #{limit}

INSERT INTO tb_crawl_job (target_no, trigger_type, status, requested_by)
SELECT #{targetId}, #{triggerType}, 'PENDING', #{requestedBy}
WHERE NOT EXISTS (
    SELECT 1
    FROM tb_crawl_job
    WHERE target_no = #{targetId}
      AND status IN ('PENDING', 'RUNNING')
)
RETURNING

mapper.update:
UPDATE tb_crawl_job
SET status = #{status},
    finished_at = now(),
    message = #{message}
WHERE crawl_job_no = #{id}
  AND status = 'RUNNING'

UPDATE tb_crawl_job
SET status = CASE WHEN attempt_count >= #{maxAttempts} THEN 'FAILED' ELSE 'PENDING' END,
    finished_at = CASE WHEN attempt_count >= #{maxAttempts} THEN now() ELSE NULL END,
    message = #{message}
WHERE status = 'RUNNING'
  AND started_at < #{cutoff}

