WHERE status = 'FAILED'

    AND reviewed = #{reviewed}


    AND failure_code = #{failureCode}

ORDER BY frst_reg_dt DESC, crawl_run_log_no DESC
LIMIT #{limit}

SELECT 
FROM tb_crawl_run_log
WHERE crawl_run_log_no = #{id}

mapper.delete:
DELETE FROM tb_crawl_document
WHERE frst_reg_dt < #{cutoff}
  AND status IN ('FAILED', 'DUPLICATE')

